parity.scriptTemplate:
import fs from 'node:fs/promises';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
const root = '<candidate-backend>';
const base = '<baseline-backend>';
const mod = (at, file) => import(pathToFileURL(at + '/' + file));
const encode = (_key, value) => value instanceof Map ? { mapEntries: [...value] }
  : value instanceof Set ? { setEntries: [...value] }
  : value && typeof value === 'object' && !Array.isArray(value)
    ? Object.fromEntries(Object.keys(value).sort().map(key => [key, value[key]])) : value;
const digest = value => createHash('sha256').update(JSON.stringify(value, encode)).digest('hex');
if (process.argv[2] === 'read') {
  const [at, input] = process.argv.slice(3), fixture = JSON.parse(await fs.readFile(input, 'utf8'));
  const { default: database } = await mod(at, 'src/lib/prisma.js');
  const { computeCollaboratorRates } = await mod(at, 'src/lib/acompanhamento/labor-cost.js');
  const { getProjectDetail } = await mod(at, 'src/lib/acompanhamento/project-detail.js');
  const { getMissionGroupDetail } = await mod(at, 'src/lib/acompanhamento/project-detail-groups.js');
  const { buildMonthlyAllocationSummary } = await mod(at, 'src/lib/allocation-monthly-report.js');
  const { loadConfirmedReviewDays } = await mod(at, 'src/lib/efetivo/allocation-review/confirmed-days.js');
  const { withProjectAccess } = await mod(at, 'src/lib/projects/access-scope.js');
  try {
    const operations = {
      explicitRates: () => computeCollaboratorRates(fixture.importId), latestRates: () => computeCollaboratorRates(),
      pointMetadata: () => computeCollaboratorRates(null, { includeIgnoredNames: true }),
      detail: () => getProjectDetail(fixture.projectId, { includeCollaboratorCosts: true, progressMode: 'current' }),
      group: () => getMissionGroupDetail(fixture.groupId, { includeCollaboratorCosts: true, progressMode: 'current' }),
      viewerGroup: () => withProjectAccess({ accountType: 'INTERNAL' }, () => getMissionGroupDetail(fixture.groupId, {
        includeCollaboratorCosts: false, includeAdminOnlyCategories: false, progressMode: 'current' })),
      confirmedDays: () => loadConfirmedReviewDays({ from: '2026-09-01', to: '2026-10-01' }, database),
      monthlyReport: async () => {
        const result = await buildMonthlyAllocationSummary({ yearMonth: '2026-09', client: database });
        assert.ok(Number.isFinite(new Date(result.generatedAt).getTime()));
        // Runtime emission time intentionally differs between the two readers.
        return { ...result, generatedAt: 'DIAGNOSTIC_GENERATION_TIME' };
      }
    };
    const hashes = {}, raw = {};
    for (const [name, operation] of Object.entries(operations)) {
      raw[name] = await operation();
      if (['detail', 'group', 'viewerGroup'].includes(name)) {
        assert.match(raw[name].progressRevision, /^[a-f0-9]{64}$/);
        raw[name] = { ...raw[name], progressRevision: 'OPAQUE_PROGRESS_REVISION' };
      }
      hashes[name] = digest(raw[name]);
    }
    await fs.writeFile('/tmp/filtro-next-parity-' + (at === root ? 'candidate' : 'control') + '-raw.json', JSON.stringify(raw, encode));
    if (globalThis.__performanceRevisionInputs) await fs.writeFile('/tmp/filtro-next-revision-' + (at === root ? 'candidate' : 'control') + '.json', JSON.stringify(globalThis.__performanceRevisionInputs));
    console.log(JSON.stringify(hashes));
  } finally { await database.$disconnect(); }
} else {
  const { default: database } = await mod(root, 'src/lib/prisma.js');
  const { seedHttpPerformanceFixture } = await mod(root, 'scripts/fixtures/http-performance.js');
  let fixture;
  const rows = [];
  try {
    fixture = await seedHttpPerformanceFixture(database, { reportCount: 120, scopeCount: 12, distributeGroupReports: true });
    const input = '/tmp/filtro-next-parity-input.json';
    await fs.writeFile(input, JSON.stringify({ importId: fixture.importId, projectId: fixture.projectId, groupId: fixture.groupId }));
    const rowId = fixture.prefix + '-review-row', dayId = fixture.prefix + '-review-day', weekId = fixture.prefix + '-review-week';
    for (const phase of ['initial', 'confirmed', 'review-changed', 'review-unconfirmed', 'shared-execution', 'consolidated', 'reference-writes']) {
      if (phase === 'confirmed') await database.allocationReviewWeek.create({ data: { id: weekId,
        weekStart: new Date('2026-09-07'), rows: { create: { id: rowId, collaboratorId: fixture.prefix + '-person-3',
          confirmedAt: new Date(), days: { create: { id: dayId, collaboratorId: fixture.prefix + '-person-3',
            workDate: new Date('2026-09-10'), kind: 'PROJECT', projects: { create: fixture.projectIds.slice(0, 2).map(projectId => ({ projectId })) } } } } } } });
      if (phase === 'review-changed') {
        await database.allocationReviewDayProject.deleteMany({ where: { dayId, projectId: fixture.projectIds[0] } });
        await database.allocationReviewDay.update({ where: { id: dayId }, data: { kind: 'TRAVEL' } });
      }
      if (phase === 'review-unconfirmed') await database.allocationReviewRow.update({ where: { id: rowId }, data: { confirmedAt: null } });
      if (phase === 'shared-execution') await database.acompanhamentoMissionGroup.update({ where: { id: fixture.groupId }, data: { laborAllocationMode: 'SHARED_EXECUTION' } });
      if (phase === 'consolidated') await database.acompanhamentoMissionGroup.update({ where: { id: fixture.groupId }, data: { laborAllocationMode: 'CONSOLIDATE_PRIMARY', primaryLaborProjectId: fixture.projectIds[0] } });
      if (phase === 'reference-writes') {
        await database.jobRole.update({ where: { id: fixture.prefix + '-role' }, data: { name: 'Cargo atualizado' } });
        await database.collaborator.update({ where: { id: fixture.prefix + '-person-3' }, data: { name: 'Pessoa atualizada' } });
      }
      const values = [];
      for (const source of [base, root]) {
        const result = spawnSync(process.execPath, [process.argv[1], 'read', source, input], { encoding: 'utf8', env: process.env, maxBuffer: 1024 * 1024, timeout: 120000 });
        assert.equal(result.status, 0, result.stderr);
        values.push(JSON.parse(result.stdout));
      }
      assert.deepEqual(values[0], values[1], phase);
      rows.push({ phase, exactEquality: true, hashes: values[0] });
    }
    await fs.writeFile('/tmp/filtro-next-parity.json', JSON.stringify(rows, null, 2));
    console.log(JSON.stringify({ phases: rows.length, equalPairs: rows.length * Object.keys(rows[0].hashes).length }));
  } finally {
    if (fixture) {
      await database.allocationReviewWeek.deleteMany({ where: { id: fixture.prefix + '-review-week' } });
      await fixture.cleanup();
    }
    await database.$disconnect();
  }
}
